// AccountSettingsScreen.tsx
// Self-contained Account Settings screen for a React Native app (iOS + Android).
// Dependencies: react, react-native only — no third-party packages required.

import React, { useCallback, useState } from 'react';
import {
  View,
  Text,
  Image,
  StyleSheet,
  ScrollView,
  Pressable,
  Switch,
  Alert,
  ActivityIndicator,
  Platform,
  SafeAreaView,
  StatusBar,
} from 'react-native';

// ---------- Types ----------

interface Profile {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface AccountSettingsScreenProps {
  profile: Profile;
  onEditProfile: () => void;
  onNavigate: (route: string) => void;
  onSignOut: () => void;
  /** Should perform the real deletion (API call) and resolve/reject. */
  onDeleteAccount: () => Promise<void>;
}

// ---------- Reusable row components ----------

interface SettingsRowProps {
  label: string;
  subtitle?: string;
  onPress?: () => void;
  destructive?: boolean;
  disabled?: boolean;
  right?: React.ReactNode;
  isLast?: boolean;
}

const SettingsRow: React.FC<SettingsRowProps> = ({
  label,
  subtitle,
  onPress,
  destructive = false,
  disabled = false,
  right,
  isLast = false,
}) => {
  const content = (
    <View style={[styles.row, !isLast && styles.rowDivider]}>
      <View style={styles.rowTextContainer}>
        <Text
          style={[styles.rowLabel, destructive && styles.rowLabelDestructive]}
          numberOfLines={1}
        >
          {label}
        </Text>
        {subtitle ? (
          <Text style={styles.rowSubtitle} numberOfLines={1}>
            {subtitle}
          </Text>
        ) : null}
      </View>
      {right !== undefined ? right : onPress ? <Text style={styles.chevron}>›</Text> : null}
    </View>
  );

  if (!onPress) {
    return content;
  }

  return (
    <Pressable
      onPress={onPress}
      disabled={disabled}
      accessibilityRole="button"
      accessibilityLabel={label}
      style={({ pressed }) => [pressed && !disabled && styles.rowPressed]}
      android_ripple={{ color: '#E0E0E0' }}
    >
      {content}
    </Pressable>
  );
};

interface SectionProps {
  title?: string;
  children: React.ReactNode;
}

const Section: React.FC<SectionProps> = ({ title, children }) => (
  <View style={styles.section}>
    {title ? <Text style={styles.sectionTitle}>{title}</Text> : null}
    <View style={styles.sectionCard}>{children}</View>
  </View>
);

// ---------- Profile row ----------

const ProfileRow: React.FC<{ profile: Profile; onPress: () => void }> = ({
  profile,
  onPress,
}) => (
  <Pressable
    onPress={onPress}
    accessibilityRole="button"
    accessibilityLabel={`Edit profile for ${profile.name}`}
    style={({ pressed }) => [styles.profileRow, pressed && styles.rowPressed]}
    android_ripple={{ color: '#E0E0E0' }}
  >
    {profile.avatarUrl ? (
      <Image source={{ uri: profile.avatarUrl }} style={styles.avatar} />
    ) : (
      <View style={[styles.avatar, styles.avatarFallback]}>
        <Text style={styles.avatarInitial}>
          {profile.name.trim().charAt(0).toUpperCase() || '?'}
        </Text>
      </View>
    )}
    <View style={styles.profileTextContainer}>
      <Text style={styles.profileName} numberOfLines={1}>
        {profile.name}
      </Text>
      <Text style={styles.profileEmail} numberOfLines={1}>
        {profile.email}
      </Text>
    </View>
    <Text style={styles.chevron}>›</Text>
  </Pressable>
);

// ---------- Main screen ----------

const AccountSettingsScreen: React.FC<AccountSettingsScreenProps> = ({
  profile,
  onEditProfile,
  onNavigate,
  onSignOut,
  onDeleteAccount,
}) => {
  const [pushEnabled, setPushEnabled] = useState(true);
  const [faceIdEnabled, setFaceIdEnabled] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const confirmDeleteAccount = useCallback(() => {
    Alert.alert(
      'Delete account',
      'This permanently deletes your account and all associated data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => {
            // Second confirmation step — deliberately harder to hit by accident.
            Alert.alert(
              'Are you absolutely sure?',
              `Type-safe confirm: deleting "${profile.email}" cannot be reversed.`,
              [
                { text: 'Cancel', style: 'cancel' },
                {
                  text: 'Yes, delete my account',
                  style: 'destructive',
                  onPress: handleDeleteAccount,
                },
              ],
              { cancelable: true },
            );
          },
        },
      ],
      { cancelable: true },
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [profile.email]);

  const handleDeleteAccount = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch (error) {
      Alert.alert(
        'Couldn\u2019t delete account',
        error instanceof Error ? error.message : 'Something went wrong. Please try again.',
      );
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount]);

  const confirmSignOut = useCallback(() => {
    Alert.alert('Sign out', 'Are you sure you want to sign out?', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Sign out', style: 'destructive', onPress: onSignOut },
    ]);
  }, [onSignOut]);

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar barStyle="dark-content" />
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        keyboardShouldPersistTaps="handled"
      >
        <ProfileRow profile={profile} onPress={onEditProfile} />

        <Section title="ACCOUNT">
          <SettingsRow label="Edit profile" onPress={onEditProfile} />
          <SettingsRow label="Change password" onPress={() => onNavigate('ChangePassword')} />
          <SettingsRow
            label="Email"
            subtitle={profile.email}
            onPress={() => onNavigate('ChangeEmail')}
            isLast
          />
        </Section>

        <Section title="PREFERENCES">
          <SettingsRow
            label="Push notifications"
            right={
              <Switch
                value={pushEnabled}
                onValueChange={setPushEnabled}
                accessibilityLabel="Toggle push notifications"
              />
            }
          />
          <SettingsRow
            label={Platform.OS === 'ios' ? 'Face ID' : 'Biometric unlock'}
            right={
              <Switch
                value={faceIdEnabled}
                onValueChange={setFaceIdEnabled}
                accessibilityLabel="Toggle biometric unlock"
              />
            }
          />
          <SettingsRow label="Language" subtitle="English" onPress={() => onNavigate('Language')} isLast />
        </Section>

        <Section title="SUPPORT">
          <SettingsRow label="Help Center" onPress={() => onNavigate('Help')} />
          <SettingsRow label="Privacy Policy" onPress={() => onNavigate('Privacy')} />
          <SettingsRow label="Terms of Service" onPress={() => onNavigate('Terms')} isLast />
        </Section>

        <Section>
          <SettingsRow label="Sign out" onPress={confirmSignOut} isLast />
        </Section>

        <Section>
          <SettingsRow
            label={isDeleting ? 'Deleting account…' : 'Delete account'}
            destructive
            disabled={isDeleting}
            onPress={confirmDeleteAccount}
            right={isDeleting ? <ActivityIndicator size="small" /> : null}
            isLast
          />
        </Section>

        <Text style={styles.versionText}>Version 1.0.0</Text>
      </ScrollView>
    </SafeAreaView>
  );
};

export default AccountSettingsScreen;

